import { z } from "zod";

/**
 * Attendance QR Token validation regex.
 * Format generated by RotatingTokenService:
 * <sessionId>.<timeBucket>.<signatureHash>
 * sessionId: 24 hex characters (MongoDB ObjectId)
 * timeBucket: integer timestamp bucket
 * signatureHash: 16+ hex characters HMAC
 */
export const QR_TOKEN_REGEX = /^[a-fA-F0-9]{24}\.\d+\.[a-fA-F0-9]{8,}$/;
export const MANUAL_ATTENDANCE_CODE_REGEX = /^[a-fA-F0-9]{6}-\d{6}$/;

/**
 * Zod schema for QR token validation with bilingual error messages
 */
export const createQrTokenSchema = (locale: string = "ar") => {
  const isAr = locale.startsWith("ar");
  return z
    .string({
      message: isAr
        ? "رمز الحضور مطلوب"
        : "Attendance token is required",
    })
    .trim()
    .min(1, {
      message: isAr ? "يرجى إدخال رمز الحضور" : "Please enter attendance token",
    })
    .refine(
      (val) => {
        // Accepts raw rotating token format OR URL containing ?t=<token>
        if (
          QR_TOKEN_REGEX.test(val) ||
          MANUAL_ATTENDANCE_CODE_REGEX.test(val)
        ) {
          return true;
        }
        try {
          const url = new URL(val);
          const t = url.searchParams.get("t");
          return !!t && QR_TOKEN_REGEX.test(t);
        } catch {
          return false;
        }
      },
      {
        message: isAr
          ? "صيغة رمز الحضور غير صالحة أو غير مكتملة (تأكد من مسح الرمز من شاشة المحاضر مباشرة)"
          : "Invalid or malformed attendance token. Please scan the current code from the instructor display.",
      },
    );
};

/**
 * Helper to extract raw token from either raw string or pasted check-in URL
 */
export function extractRawToken(input: string): string {
  const trimmed = input.trim();
  if (QR_TOKEN_REGEX.test(trimmed)) {
    return trimmed;
  }
  if (MANUAL_ATTENDANCE_CODE_REGEX.test(trimmed)) {
    return trimmed.toUpperCase();
  }
  try {
    const url = new URL(trimmed);
    const tokenParam = url.searchParams.get("t");
    if (tokenParam && QR_TOKEN_REGEX.test(tokenParam)) {
      return tokenParam;
    }
  } catch {
    // Not a valid URL, return trimmed as fallback
  }
  return trimmed;
}

/**
 * Zod schema for starting an attendance session
 */
export const createStartSessionSchema = (locale: string = "ar") => {
  const isAr = locale.startsWith("ar");
  return z.object({
    courseCode: z
      .string({
        message: isAr ? "كود المقرر مطلوب" : "Course code is required",
      })
      .min(1, {
        message: isAr ? "كود المقرر مطلوب" : "Course code is required",
      }),
sessionType: z.enum(["lecture", "section", "lab"] as const, {
  message: isAr ? "نوع الجلسة غير صالح" : "Invalid session type",
}),
    level: z.number().min(1).max(4),
    group: z.string().optional(),
    section: z.string().optional(),
    sessionDurationMinutes: z
      .number()
      .min(5, {
        message: isAr
          ? "مدة الجلسة لا تقل عن 5 دقائق"
          : "Minimum session duration is 5 minutes",
      })
      .max(180, {
        message: isAr
          ? "أقصى مدة للجلسة 180 دقيقة"
          : "Maximum session duration is 180 minutes",
      }),
    lateThresholdMinutes: z
      .number()
      .min(1, {
        message: isAr
          ? "مهلة التأخير دقيقة واحدة على الأقل"
          : "Minimum late threshold is 1 minute",
      })
      .max(60, {
        message: isAr
          ? "مهلة التأخير لا تتجاوز 60 دقيقة"
          : "Late threshold cannot exceed 60 minutes",
      }),
    qrRotationSeconds: z
      .number()
      .min(10, {
        message: isAr
          ? "معدل التجديد 10 ثوانٍ على الأقل"
          : "Minimum rotation is 10 seconds",
      })
      .max(120, {
        message: isAr
          ? "معدل التجديد 120 ثانية كحد أقصى"
          : "Maximum rotation is 120 seconds",
      }),
  });
};

/**
 * Zod schema for manual check-in of a student by staff
 */
export const createManualCheckInSchema = (locale: string = "ar") => {
  const isAr = locale.startsWith("ar");
  return z.object({
    studentCode: z
      .string({
        message: isAr
          ? "كود الطالب الأكاديمي مطلوب"
          : "Student code is required",
      })
      .trim()
      .min(3, {
        message: isAr
          ? "كود الطالب يجب أن يتكون من 3 أحرف/أرقام على الأقل"
          : "Student code must be at least 3 characters",
      }),
status: z.enum(["present", "late"] as const, {
  message: isAr ? "الحالة غير صالحة" : "Invalid status",
}),
    reason: z
      .string()
      .max(200, {
        message: isAr
          ? "السبب لا يتجاوز 200 حرف"
          : "Reason cannot exceed 200 characters",
      })
      .optional(),
  });
};

/**
 * Bilingual translator for Attendance API errors
 */

interface ApiErrorShape {
  response?: {
    data?: {
      message?: string;
    };
  };
  message?: string;
}

export function getAttendanceErrorMessage(
  error: unknown,
  locale: string = "ar",
): string {
  const isAr = locale.startsWith("ar");
  const err = error as ApiErrorShape | null | undefined;
  const rawMsg = err?.response?.data?.message || err?.message || "";

  const normalized = String(rawMsg).toLowerCase();

  if (
    normalized.includes("جلسة الحضور مغلقة") ||
    normalized.includes("انتهت مدة صلاحيتها") ||
    normalized.includes("session is closed") ||
    normalized.includes("session closed") ||
    normalized.includes("expired")
  ) {
    return isAr
      ? "جلسة الحضور مغلقة أو انتهت مدة صلاحيتها؛ لا يمكن تسجيل الحضور أو توليد رمز جديد."
      : "Attendance session is closed or has expired; cannot register attendance or generate new QR.";
  }

  if (
    normalized.includes("غير مسجل") ||
    normalized.includes("not enrolled") ||
    normalized.includes("not registered")
  ) {
    return isAr
      ? "أنت غير مسجل في هذا المقرر الدراسي، ولا يمكنك تسجيل الحضور فيه."
      : "You are not enrolled in this course and cannot register attendance.";
  }

  if (
    normalized.includes("مسبقاً") ||
    normalized.includes("already checked in") ||
    normalized.includes("already recorded")
  ) {
    return isAr
      ? "تم تسجيل حضورك مسبقاً في هذه الجلسة بنجاح."
      : "You have already checked in for this session.";
  }

  if (
    normalized.includes("رمز الحضور") ||
    normalized.includes("token") ||
    normalized.includes("invalid") ||
    normalized.includes("tamper")
  ) {
    return isAr
      ? "رمز الحضور غير صالح أو منتهي الصلاحية؛ يرجى مسح أحدث رمز من شاشة المحاضر مباشرة."
      : "Invalid or expired attendance token. Please scan the latest code directly from the screen.";
  }

  if (
    normalized.includes("غير مصرح") ||
    normalized.includes("forbidden") ||
    normalized.includes("unauthorized")
  ) {
    return isAr
      ? "غير مصرح لك بتسجيل الحضور لهذه الجلسة."
      : "You are not authorized to check in for this session.";
  }

  return (
    rawMsg ||
    (isAr
      ? "حدث خطأ أثناء معالجة الحضور"
      : "An error occurred processing attendance")
  );
}